use forge_domain :: { Context , ContextMessage , Role , Transformer } ; use forge_domain :: { Context , ContextMessage , ReasoningFull , Role , TextMessage , ToolCallArguments , ToolCallFull , ToolCallId , Transformer , } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Drops assistant messages whose only content is reasoning."] # [doc = ""] # [doc = " Anthropic rejects an assistant message whose final content block is"] # [doc = " `thinking`, and Bedrock applies the same constraint. A message with"] # [doc = " `reasoning_details` but no text or tool calls serializes to that invalid"] # [doc = " shape. It typically comes from a turn that was aborted mid-tool-call,"] # [doc = " compacted away, or cut short by a stream disconnect; the stranded"] # [doc = " reasoning has nothing to anchor, so dropping the whole message is the"] # [doc = " safe replay shape."] pub (crate) struct DropReasoningOnlyMessages ;